<script lang="ts">import { Link, navigate } from 'svelte-routing'; import { login } from '../auth/auth'; let email = $state('avery@example.com'); let password = $state('password123'); let error = $state(''); let isValid = $derived(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && password.length > 0); async function submit(event: SubmitEvent): Promise<void> { event.preventDefault(); if (!isValid) return; if (await login(email, password)) navigate('/dashboard'); else error = 'Invalid email or password' }</script><main class="grid min-h-screen place-items-center bg-surface p-5"><form onsubmit={submit} class="w-full max-w-md rounded-panel bg-card p-8 shadow-sm ring-1 ring-line"><div class="text-center"><p class="text-2xl font-bold text-navy">Shoply</p><h1 class="mt-6 text-2xl font-bold text-navy">Welcome back</h1><p class="mt-2 text-muted">Sign in to continue shopping.</p></div><label class="mt-7 block text-sm font-semibold text-navy">Email<input bind:value={email} type="email" class="mt-2 w-full rounded-lg border border-line px-3 py-3 font-normal outline-primary"/></label><label class="mt-4 block text-sm font-semibold text-navy">Password<input bind:value={password} type="password" class="mt-2 w-full rounded-lg border border-line px-3 py-3 font-normal outline-primary"/></label>{#if error}<p class="mt-3 text-sm text-danger">{error}</p>{/if}<button disabled={!isValid} class="mt-6 w-full rounded-xl bg-primary px-4 py-3 font-semibold text-white disabled:opacity-50">Sign in</button><p class="mt-5 text-center text-sm text-muted">New here? <Link to="/signup" class="font-semibold text-primary">Create an account</Link></p><p class="mt-5 rounded-lg bg-blue-50 p-3 text-center text-xs text-primary">Demo: avery@example.com / password123</p></form></main>
